const featureItems=[
{icon:'↗',category:'01 / COLLECTION',title:'A daily pulse on airfares.',short:'A repeatable sampling plan across airlines, booking platforms and five departure horizons.',flow:['Route basket','Daily scheduler','Fare sources','Raw records'],tech:'Python + Playwright · cron',status:'Planned real-source collection',detail:'A fixed daily run searches the same route basket for departures 1, 7, 15, 30 and 45 days ahead. Playwright will extract comparable flight offers from supported sources, recording search time and availability alongside price.',extra:'Collectors will respect source terms, robots.txt and rate limits, with bounded retries and clear failure logs. A blocked or sold-out search must not become a fabricated fare. The included service supports scheduling and a scraper adapter interface; real airline adapters still need implementation.'},
{icon:'▤',category:'02 / FARE HISTORY',title:'A database behind every fare.',short:'Keep structured observations and source provenance so every change can be traced.',flow:['Raw offer','Validate fields','Store snapshot','Query history'],tech:'PostgreSQL · FastAPI',status:'PostgreSQL planned · SQLite prototype available',detail:'The planned fare database stores route, carrier, flight, fare class, departure date, search timestamp, booking horizon, source and availability. Base fare, taxes, UDF and other fees roll up to the total payable fare.',extra:'Timestamped snapshots preserve the history used to define base periods and audit calculations. FastAPI will serve observations and calculated indices to the dashboard. The existing downloadable service uses SQLite; the published page itself is not a hosted PostgreSQL database.'},
{icon:'≋',category:'03 / DATA QUALITY',title:'Clean data. Genuine movement.',short:'Normalize fare fields and remove duplicate offers while retaining real price surges.',flow:['Normalize','Deduplicate','Match product','Quality checks'],tech:'Pandas + NumPy',status:'Basic validation available · full matching planned',detail:'Compare the same currency, passenger count, cabin and fare product. Normalize fields and identify duplicate offers without treating a genuine fare surge as an error.',extra:'Sold-out fares should be NULL with an availability status, never zero. A documented missing-price policy must govern unmatched items. Fixed comparison groups prevent heavily sampled sources from dominating the index. The prototype currently validates positive fares and removes duplicate observation IDs.'},
{icon:'∏',category:'04 / PRICE INDEX',title:'Jevons, made understandable.',short:'Measure price movement with the geometric mean of matched fare relatives.',flow:['Current ÷ base','Log relatives','Average + exp','Index × 100'],tech:'NumPy · matched historical fare basket',status:'Illustrative index available · matched base series planned',detail:'For each matched fare item j, calculate rⱼ = Pⱼ,ₜ / Pⱼ,₀. Within a route and horizon, the Jevons index is I = 100 × exp(Σ ln(rⱼ) / n). An index of 110 means a 10% increase relative to the base period.',extra:'Example: relatives 1.10 and 0.90 produce 100 × √0.99 = 99.50. The dashboard currently compares observations with one demo base fare per route; production requires an item-specific historical base and a fixed comparable basket.'},
{icon:'⌁',category:'05 / NATIONAL VIEW',title:'Five horizons. Clear signals.',short:'Follow near-departure and advance-booking prices without mixing their signals.',flow:['Route indices','PSD weights','National index','5 horizon series'],tech:'Pandas + NumPy · React + Vite',status:'Demo horizon dashboard available',detail:'Aggregate route indices using I national,h = Σ wᵣ × Iᵣ,h, with route weights summing to 1. Publish separate series for T+1, T+7, T+15, T+30 and T+45.',extra:'Use PSD route weights when available; DGCA traffic shares are a prototype fallback only. Combine horizons only with authoritative booking-share weights. Daily, weekly and monthly reporting is planned. Current weights are illustrative, and incomplete route coverage leaves the national index unavailable.'},
{icon:'✓',category:'06 / VALIDATION',title:'Check the signal before release.',short:'Track coverage, compare benchmarks and make research results reproducible.',flow:['30+ day backtest','Coverage review','DGCA comparison','Publish results'],tech:'Docker + Pytest · REST API',status:'Production validation planned',detail:'The proposed validation process back-tests at least 30 days, reviews missing observations and compares against the DGCA benchmark at monthly frequency. Differences in basket, timing and fare definitions must be documented.',extra:'Automated checks will cover matching rules, route weights, missing-data behavior and index calculations. Docker provides a reproducible deployment environment; Pytest supports regression testing. The existing prototype is an exploratory signal, not an official CPI series or a completed validated production pipeline.'}
];
const flowHTML=steps=>'<div class="pipeline">'+steps.map((s,i)=>(i?'<i aria-hidden="true">→</i>':'')+'<span>'+esc(s)+'</span>').join('')+'</div>';
$('#feature-grid').innerHTML=featureItems.map((f,i)=>`<button class="feature-card" data-feature="${i}" aria-haspopup="dialog"><div class="feature-art"><div class="feature-meta">${f.category}<span>${f.icon}</span></div>${flowHTML(f.flow.slice(0,3))}</div><div class="feature-copy"><span class="feature-tech">${f.tech}</span><h3>${f.title}</h3><p>${f.short}</p><span class="feature-link">Explore feature <b aria-hidden="true">↗</b></span></div></button>`).join('');
document.querySelectorAll('[data-feature]').forEach(b=>b.onclick=()=>{const f=featureItems[Number(b.dataset.feature)];$('#feature-category').textContent=f.category;$('#feature-title').textContent=f.title;$('#feature-body').innerHTML=`<p class="detail-lead">${f.detail}</p>${flowHTML(f.flow)}<h3>How it works</h3><p>${f.extra}</p><div class="detail-status"><b>${f.tech}</b><p>${f.status}</p></div>`;$('#feature-detail').showModal()});
$('#feature-close').onclick=()=>$('#feature-detail').close();
